def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find maximal diagonal runs of matching non-background cells.
    for dr, dc in ((1, 1), (1, -1)):
        seen = set()
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or (r, c) in seen:
                    continue
                cells = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    cells.append((rr, cc))
                    seen.add((rr, cc))
                    rr += dr
                    cc += dc
                # Only process runs that begin at their upper endpoint.
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                if len(cells) < 2:
                    continue

                ends = (cells[0], cells[-1])
                directions = ((-dr, -dc), (dr, dc))
                candidates = []
                for end, (er, ec) in zip(ends, directions):
                    nr, nc = end[0] + er, end[1] + ec
                    free = 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg
                    candidates.append((free, end, (er, ec)))

                viable = [x for x in candidates if x[0]]
                if len(viable) == 1:
                    chosen = viable
                elif len(viable) == 2:
                    # If one endpoint is attached to another color, extend from
                    # the opposite endpoint.
                    attached = []
                    for _, end, _ in viable:
                        r0, c0 = end
                        attached.append(any(
                            0 <= r0 + ar < h and 0 <= c0 + ac < w
                            and grid[r0 + ar][c0 + ac] not in (bg, color)
                            for ar, ac in ((1, 0), (-1, 0), (0, 1), (0, -1))
                        ))
                    if attached.count(True) == 1:
                        chosen = [viable[1 - attached.index(True)]]
                    else:
                        chosen = []
                else:
                    chosen = []

                for _, end, (er, ec) in chosen:
                    rr, cc = end[0] + er, end[1] + ec
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += er
                        cc += ec

    return out
